using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research agent. When given a topic, use the WebSearch tool to find " +
    "relevant information from multiple angles, use the TakeNote tool to record key " +
    "findings as you go, then provide a comprehensive summary of your research.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of large language models on software development in 2025";

Console.WriteLine($"Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic thoroughly. Search for information from multiple " +
        $"angles, take notes on key findings, then summarize everything.\n\nTopic: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = [.. AIFunctionFactory.Create(researchTools)],
};

await foreach (var message in agent.InvokeStreamingAsync(messages, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research Notes ---");
var noteService = host.Services.GetRequiredService<NoteService>();
foreach (var note in noteService.GetNotes())
{
    Console.WriteLine($"• {note}");
}

// --- Services and Tools ---

public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public void Add(string note) => _notes.Add(note);
    public IReadOnlyList<string> GetNotes() => _notes;
}

public sealed class ResearchTools(NoteService noteService)
{
    [Description("Search the web for information on a query. Returns relevant search results.")]
    public static string WebSearch(
        [Description("The search query to look up")] string query)
    {
        // Simulated web search — replace with a real search API (Bing, Google, etc.)
        Console.WriteLine($"  [WebSearch] Searching: \"{query}\"");
        return $"""
            Search results for "{query}":
            1. Recent studies show significant developments in this area with multiple research papers published in 2024-2025.
            2. Industry reports indicate growing adoption and investment trends related to "{query}".
            3. Expert analysis suggests both opportunities and challenges ahead for this topic.
            (In production, integrate a real search API such as Bing Web Search or Google Custom Search.)
            """;
    }

    [Description("Take a note to record an important finding during research.")]
    public string TakeNote(
        [Description("The note content to record")] string note)
    {
        noteService.Add(note);
        Console.WriteLine($"  [TakeNote] Recorded: \"{note[..Math.Min(note.Length, 80)]}...\"");
        return $"Note recorded: {note}";
    }
}

