using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;
using OpenAI.Chat;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Build the chat client with automatic function invocation
var openAIClient = new OpenAIClient(apiKey);
IChatClient chatClient = new ChatClientBuilder(openAIClient.GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// Create the research agent
var noteService = new NoteService();
var researchTools = new ResearchTools(noteService);

var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    """
    You are a research agent. When given a topic:
    1. Use WebSearch to find information from multiple angles (at least 3 searches).
    2. Use TakeNote to record each key finding as you discover it.
    3. After gathering enough information, provide a comprehensive summary.
    Always search before summarizing. Be thorough but concise.
    """,
    "ResearchAgent");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of large language models on software development in 2025";

Console.WriteLine($"🔍 Researching: {topic}\n");

var tools = new AITool[]
{
    AIFunctionFactory.Create(ResearchTools.WebSearch),
    AIFunctionFactory.Create(researchTools.TakeNote),
};

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Tools = [.. tools],
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

var prompt = $"""
    Research the following topic thoroughly. Search for information from multiple
    angles, take notes on key findings, then provide a comprehensive summary.

    Topic: {topic}
    """;

await foreach (var msg in agent.RunStreamingAsync(prompt, options: runOptions))
{
    if (!string.IsNullOrEmpty(msg.Text))
    {
        Console.Write(msg.Text);
    }
}

Console.WriteLine("\n\n📝 Research Notes Collected:");
Console.WriteLine(new string('─', 40));
foreach (var note in noteService.GetNotes())
{
    Console.WriteLine($"  • {note}");
}

// --- Services and Tools ---

public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public void Add(string note) => _notes.Add(note);
    public IReadOnlyList<string> GetNotes() => _notes;
}

public sealed class ResearchTools(NoteService noteService)
{
    [Description("Search the web for information on a query. Returns relevant search result snippets.")]
    public static string WebSearch(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🌐 [WebSearch] \"{query}\"");

        // Simulated web search results — replace with a real API (Bing Search, Google Custom Search, etc.)
        return $"""
            Search results for "{query}":
            1. Recent studies and reports (2024-2025) show significant developments in this area,
               with industry adoption accelerating and new frameworks emerging.
            2. Experts highlight both transformative potential and important challenges,
               including scalability, ethical considerations, and integration complexity.
            3. Market analysis indicates substantial investment growth and evolving best practices
               across multiple sectors related to "{query}".
            Note: In production, replace this with a real search API integration.
            """;
    }

    [Description("Take a note to record an important finding during research. Use this to track key facts and insights.")]
    public string TakeNote(
        [Description("The note content summarizing a key finding")] string note)
    {
        noteService.Add(note);
        var preview = note.Length > 60 ? note[..60] + "..." : note;
        Console.WriteLine($"  📌 [TakeNote] \"{preview}\"");
        return $"Note saved successfully.";
    }
}

